// lib/widgets/welcome_cast.dart
//
// The squares are generated by scripts/welcome_cast.py, which renders each
// picture: run it again rather than editing them by hand. See
// docs/ROUNDED_PIXEL_ART.md, "The cast".

/// One of the pictures the welcome screen's rooster hands over to.
///
/// Each is drawn on the rooster's own grid -- the same 20 x 25 squares, the
/// same pitch, the same canvas -- so a tile of one can flip over and be a
/// tile of the next.
class CastMember {
  final String name;
  final String asset;

  /// Where the flip into this picture starts: its eye, or its middle.
  final ({int row, int column}) eye;

  /// Which squares hold the subject, row by row, `#` for filled.
  final List<String> squares;

  /// For a butterfly: the column its body is on, which its wings beat
  /// about while it is on screen. Null for everything that keeps still.
  final double? flapsAbout;

  const CastMember({
    required this.name,
    required this.asset,
    required this.eye,
    required this.squares,
    this.flapsAbout,
  });
}

